{
 "rules": [
  {
   "rule_id": "KBYY-S2-R19-01",
   "status": "OK",
   "label": "예금잔액 10,000원 미만 무거래 거래중지",
   "source": {
    "quote": "예금잔액이 10,000원 미만이며, 1년 이상 입출금 거래가 없는 계좌"
   },
   "condition": {
    "and": [
     {
      "<": [
       {
        "var": "account.balance"
       },
       10000
      ]
     },
     {
      ">=": [
       {
        "count_events": {
         "event": "WITHDRAWAL",
         "within": {
          "ref": "$window"
         }
        }
       },
       0
      ]
     }
    ]
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "account.last_transaction_date",
       "offset_months": -12,
       "day": "first"
      },
